from content_core import *
def build():
 out=[]
 def a(topic,sub,stem,ans,chk,sol,wrong,art=''):
  n=len(out)+1;out.append(item(12,'november-mock',n,topic,sub,min(5,(n+4)//5),stem,ans,chk,sol,wrong,art,True))
 a(AR,'Unit ratios','A mixture uses syrup and water in ratio 2:7 by volume. After 6 litres of syrup are added to 27 litres of mixture, what fraction of the new mixture is syrup?',F(4,11),F(27*F(2,9)+6,33),'Initially there are 27×2/9=6 litres of syrup. The new mixture contains 12 in a total of 33 litres, hence 4/11.',[F(2,9),F(1,3),F(2,5),F(5,11)])
 a(SEQ,'Successive differences','A staircase of display cubes uses rows of 2, 5, 8, … cubes. How many cubes are in its first 12 rows together?',222,sum(2+3*i for i in range(12)),'The last row has 2+11×3=35. Pair first and last; there are six pairs each totalling 37, so 222 cubes.',[204,210,216,228])
 a(ALG,'Logarithms','A number x satisfies log base 3 of x minus log base 3 of 4 equals 2. What is x?',36,next(x for x in range(1,100) if F(x,4)==3**2),'Combine the logarithms to get log₃(x/4)=2. Thus x/4=9 and x=36.',[12,18,27,81])
 a(PRO,'Weighted means','A committee of 12 has mean age 30. Two members with mean age 42 leave. What is the mean age of the remaining members?',F(138,5),F(12*30-2*42,10),'The total age decreases from 360 to 276. Dividing by 10 remaining members gives 138/5.',[26,27,28,29])
 a(NT,'Last digits','What is the last digit of 3²⁰²⁶ + 7²⁰²⁶?',8,(pow(3,2026,10)+pow(7,2026,10))%10,'Both last-digit cycles have length four. Since 2026≡2 mod 4, both terms end in 9; their sum ends in 8.',[0,2,4,6])
 a(GEO,'Angles','In a regular polygon, an interior angle is seven times its exterior angle. How many diagonals does the polygon have?',104,len([1 for i,j in combinations(range(16),2) if (j-i) not in (1,15)]),'Eight exterior angles equal 180°, so one is 22.5°. There are 16 sides. Remove the 16 sides from C(16,2)=120 pairs of vertices to get 104 diagonals.',[88,96,112,120])
 a(ALG,'Conjugates','Let z=(3+i)/(1−i). What is |z|²?',5,round(abs((3+1j)/(1-1j))**2),'Squared moduli multiply and divide: |3+i|²/|1−i|²=10/2=5.',[2,F(5,2),8,10])
 a(CNT,'Compositions','A positive integer is called a split-total if it is represented by the ordered sum of three positive odd numbers. How many representations does 15 have?',28,sum(x+y+z==15 for x,y,z in product(range(1,16,2),repeat=3)),'Write each odd part as 2u+1. Then u+v+w=6 in nonnegative integers. Stars and bars gives C(8,2)=28.',[15,21,35,36])
 a(TRIG,'Trigonometric identities','An acute angle θ has tan θ=3/4. What is cos(2θ)?',F(7,25),(1-F(3,4)**2)/(1+F(3,4)**2),'Use a 3–4–5 right triangle: cosine 4/5 and sine 3/5. Their squared difference is (16−9)/25=7/25.',[F(3,5),F(4,5),F(12,25),F(24,25)])
 a(NT,'Prime valuations','Find the exponent of 3 in 36! divided by 12!.',12,sum(sum(n%(3**j)==0 for j in range(1,5)) for n in range(13,37)),'Legendre’s count gives 12+4+1=17 factors of 3 in 36! and 4+1=5 in 12!. The quotient contains 12.',[8,10,13,17])
 a(SEQ,'Exponential recurrences','A sequence has b₀=4 and bₙ₊₁=3bₙ−2. What is b₅?',730,1+(4-1)*3**5,'Subtract the fixed point 1: bₙ₊₁−1=3(bₙ−1). Therefore b₅=1+3×3⁵=730.',[243,486,729,972])
 a(PRO,'Discrete expectation','Four fair six-sided dice are rolled. Let X be the number of different face values displayed. What is E[X]?',F(671,216),F(sum(len(set(p)) for p in product(range(6),repeat=4)),6**4),'For one face the probability of appearing is 1−(5/6)⁴. Sum the six face indicators: 6[1−625/1296]=671/216.',[3,F(7,2),F(65,24),4])
 a(GEO,'Inscribed circles','Three mutually tangent circles of radii 2, 3 and 4 are externally tangent in pairs. What is the area squared of the triangle joining their centres?',216,9*(9-5)*(9-7)*(9-6),'The three centre distances are 5, 6 and 7. The semiperimeter is 9. Heron gives area²=9×4×3×2=216.',[108,144,196,225])
 a(ALG,'Polynomial factors','The positive coefficient c is chosen so x³−4x²+cx−6 has root 2. What is the sum of the squares of the other two roots, counted with multiplicity?',-2,round(((1+complex(0,math.sqrt(2)))**2+(1-complex(0,math.sqrt(2)))**2).real),'Substitution at 2 gives 8−16+2c−6=0, so c=7. Division by x−2 leaves x²−2x+3. Its roots have sum 2 and product 3, so the sum of their squares is 4−6=−2.',[-4,0,2,4])
 a(TRIG,'Trigonometric periods','How many distinct solutions in 0 ≤ x < 2π satisfy sin(3x)=sin(x)?',6,len({round(x,9) for x in [t*math.pi for t in range(2)]+[(2*t+1)*math.pi/4 for t in range(4)]}),'Equal sines give 3x=x+2kπ or 3x=π−x+2kπ. The first gives two multiples of π; the second gives four odd multiples of π/4. The lists are disjoint, for 6.',[4,5,7,8])
 a(CNT,'Inclusion–exclusion','Eight different letters include A, B and C. In how many permutations do A and B occur next to each other while B and C do not?',8640,sum(abs(p.index(0)-p.index(1))==1 and abs(p.index(1)-p.index(2))!=1 for p in permutations(range(8))),'Contract AB or BA: 2×7! permutations. With both adjacencies, B is in the middle of ABC or CBA, giving 2×6!. Subtract to get 8640.',[7200,7920,10080,11520])
 a(NT,'Digital representation','A positive integer in base b is written 121; in base b+2 it is written 81. What is its decimal value?',81,next((b+1)**2 for b in range(7,50) if b+2>8 and (b+1)**2==8*(b+2)+1),'The two expressions are (b+1)² and 8b+17. Equating gives (b−8)(b+2)=0. Only b=8 is a valid base; 121 in base 8 is 64+16+1=81.',[64,100,121,144])
 a(GEO,'Coordinate optimisation','A point (t,0) on the x-axis is joined by line segments to (1,4) and (8,3). What is the square of the least possible total length?',98,(8-1)**2+(3+4)**2,'Reflect (1,4) to (1,−4). The two segments then form a broken line no shorter than the straight line to (8,3). That segment crosses the axis, so equality occurs. Its squared length is 7²+7²=98.',[50,74,81,100])
 a(ALG,'Integer polynomials','The polynomial x⁴+ax²+16 has four distinct real roots that are all integers. What is the sum of all possible values of |a|?',17,sum({u*u+v*v for u,v in combinations(range(1,17),2) if u*u*v*v==16}),'Roots occur as ±u, ±v with distinct positive u,v. Their squares multiply to 16, so uv=4 and the only distinct pair is 1,4. Thus a=−(1+16)=−17, giving 17.',[8,16,20,25])
 a(PRO,'Geometric probability','A point is uniformly distributed in the unit square. What is the probability that its distances to the two coordinate axes have sum less than 1 and differ by less than 1/2?',F(3,8),F(1,2)-2*F(1,2)*F(1,2)*F(1,4),'The triangle x+y<1 has area 1/2. The line x−y=1/2 cuts off a triangle with base 1/2 on the x-axis and height 1/4, of area 1/16. The corresponding y-side triangle is congruent. Subtract twice 1/16 to obtain 3/8.',[F(1,4),F(5,16),F(7,16),F(1,2)])
 a(SEQ,'Iteration','Define f(x)=(x−1)/(x+1). Starting with x=3, apply f exactly 2026 times. What is the absolute value of the result?',F(1,3),abs((lambda n: [F(3),F(1,2),F(-1,3),F(-2)][n%4])(2026)),'The first four values after starting are 1/2, −1/3, −2, 3. They form a cycle of length four. Since 2026≡2 mod 4, the result is −1/3, whose absolute value is 1/3.',[F(1,2),F(2,3),2,3])
 a(CNT,'Necklaces','How many different circular necklaces have eight beads, exactly four black and four white, if rotations are identified but mirror images are not identified unless a rotation matches them?',10,len({min(s[i:]+s[:i] for i in range(8)) for s in product('BW',repeat=8) if s.count('B')==4}),'Average the fixed colourings over the eight rotations. Identity fixes 70; the half-turn fixes C(4,2)=6. Each quarter-turn fixes 2; odd turns fix none. Thus (70+6+2+2)/8=10.',[8,9,12,14])
 a(NT,'GCD sums','What is the sum of gcd(k,30) over 1 ≤ k ≤ 30?',135,sum(math.gcd(k,30) for k in range(1,31)),'For each divisor d of 30 the count of k with gcd=d is φ(30/d). For d=1,2,3,5,6,10,15,30 the contributions are 8,16,12,10,24,20,15,30 respectively. Their sum is 135.',[105,120,150,180])
 a(ALG,'Complex roots','Let ω be a nonreal cube root of unity. Compute the squared modulus of (1−ω)⁵/(1−ω²)².',27,round(abs((1-complex(-.5,math.sqrt(3)/2))**5/(1-complex(-.5,math.sqrt(3)/2)**2)**2)**2),'The two nonreal cube roots are conjugates. Each squared distance to 1 is (1+1/2)²+3/4=3. The squared modulus of the quotient is 3⁵/3²=27.',[3,9,18,81])
 a(LOG,'Extremal divisibility','Select a subset of {1,2,…,30} in which no chosen number is twice another chosen number. What is the largest possible size?',20,sum(((sum(1 for j in range(6) if d*(2**j)<=30)+1)//2) for d in range(1,31,2)),'Partition by odd part d into doubling chains d,2d,4d,… . On a chain of length L, at most ⌈L/2⌉ can be chosen, attained by alternating entries. The chain lengths for odd d=1,3,…,29 are 5,4,3,3,2,2,2,2,1,1,1,1,1,1,1. Their alternating maxima sum to 20.',[15,18,19,21])
 return out
